const bsOffcanvas=new bootstrap.Offcanvas('#oCNav')
$(document).on('click','.lbc',function(){logButtonClick(this)});function logButtonClick(t){var d={'target':$(t).attr('href'),'url':window.location.pathname,'detail':$(t).attr('aria-describedby')};$.ajax({type:'POST',url:'/log-button-click',data:d,});return!1}
$(document).on('click','.mbtn',function(t){const url=$(this).attr('href')=='/'?'':new URL($(this).attr('href'));const slug=url.pathname;const searchString=url?url.search:'';const queryString=searchString.toString().replace('?','');ajaxGetPageContent(slug,queryString,t);bsOffcanvas.hide();return!1});function setActiveNavItem(url){$('#oCNav .active').removeClass('active');var adjustedUrl=url=='/'||url==''?url:url.replace('/','').replaceAll('/','-');adjustedUrl=adjustedUrl.trim();if(url!='/')
$('.navbar-nav li.'+adjustedUrl).addClass('active');else $('.navbar-nav li').first().addClass('active')}
function handlePopState(event){if(event.state.page){ajaxGetPageContent(event.state.page,'',event,!1)}};window.onpopstate=handlePopState;function ajaxGetPageContent(slug,queryString,event,addToHistory=!0){removeAllAlerts();var url=slug+(queryString&&queryString.length>0?'?'+queryString:'');if(addToHistory){var page=event.state?event.state.page:slug;var title=event.state?event.state.title:document.title;history.pushState({page:page,title:title},title,url)}
setActiveNavItem(slug);$.ajax({type:'GET',url:slug+'?header=false&footer=false'+(queryString&&queryString.length>0?'&'+queryString:''),success:function(data){$('.page-content').html(data);$(window).scrollTop(0)}}).done(function(){if(!slug||slug.length==0||slug=='/'){$('header.menu-bar').removeClass('menu-bar-bg')}else{$('header.menu-bar').addClass('menu-bar-bg')}
ajaxGetPageMetaData(slug)});return!1}
function ajaxGetPageMetaData(slug){$.ajax({type:'GET',url:'/meta-data'+slug,success:function(data){if(data){var json=$.parseJSON(data);$('meta[name=description]').attr('content',json.description);$('meta[name=keywords]').attr('content',json.keywords);$('head title').text(json.title);$('link[rel="canonical"]').attr('href',window.location.href);$('meta[property="og:description"]').attr('content',json.description);$('meta[property="og:type"]').attr('content',window.location.href.includes('/blog/')?'article':'website');$('meta[property="og:title"]').attr('content',json.title);$('meta[property="og:URL"]').attr('content',window.location.href)}}})}
$(document).ajaxSend(function(){showOverlay()});$(document).ajaxStop(function(){hideOverlay()});function showOverlay(){$('#overlay').fadeIn(300);$('body').css({'overflow':'hidden','padding-right':'17px'})}
function hideOverlay(){setTimeout(function(){$('#overlay').fadeOut(300);$('body').css({'overflow':'auto','padding-right':''})},250)}
function capitalizeFirstLetter(string){return string.charAt(0).toUpperCase()+string.slice(1)}
function removeAllAlerts(){$('.alert').remove()}
$(document).on('click','.ajaxForm button',function(){let errors=[];let form=$(this).closest('form');let formId=form.attr('id');let action=form.attr('action');showOverlay();form.find('.required').each(function(t){if(!$(this).val()){errors.push(capitalizeFirstLetter(this.name)+' is required')}});form.find('.alert-danger').remove();form.find('.alert-success').remove();if(errors.length>0){form.prepend('<div class="alert alert-danger" role="alert">'+errors.join('<br/>')+'.</div>');hideOverlay()}else{$.ajax({type:'POST',url:action+'?header=false&footer=false',data:form.serializeArray(),dataType:"json",success:function(data){if(data.error&&data.error.length>0){form.prepend('<div class="alert alert-danger" role="alert">'+data.error+'</div>')}
if(data.success&&data.success.length>0){form[0].reset();form.prepend('<div class="alert alert-success" role="alert">'+data.success+'</div>')}}}).done(function(){hideOverlay()})}
return!1});$(document).on('scroll',function(){if($(".home-callout").length){var header=$('header.menu-bar');var hieghtThreshold=$(".home-callout").offset().top-150;var scroll=$(window).scrollTop();if(scroll>=hieghtThreshold){header.addClass('menu-bar-bg')}else{header.removeClass('menu-bar-bg')}}});AOS.init({duration:900,easing:'ease-out-cubic'});window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments)}
